(function(root){'use strict';
const URL='https://api.albionfreemarket.com/be/dataclient/globalMultipliers',KEY='albion-server-economy-v1',IDS={0:'west',1:'east',2:'europe'},MAX_AGE=48*3600000,CACHE_AGE=6*3600000;
function parse(rows,now=Date.now()){const result={};if(!Array.isArray(rows))throw Error('Неверный ответ источника поправки');for(const row of rows){const server=IDS[row?.serverId],value=row?.globalMultiplier,updated=Date.parse(row?.updatedAt);if(!server||typeof value!=='number'||!Number.isFinite(value)||value<=0||value>100||!Number.isFinite(updated)||updated>now+300000||now-updated>MAX_AGE)continue;if(!result[server]||updated>Date.parse(result[server].updatedAt))result[server]={value,updatedAt:new Date(updated).toISOString(),checkedAt:now};}return result;}
function create({fetcher,storage,clock=()=>Date.now(),notify=()=>{}}){let records={},pending,error='',lastCheck=0;try{const raw=JSON.parse(storage?.getItem(KEY)||'{}');for(const server of Object.values(IDS)){const row=raw?.[server];if(row&&Number.isFinite(row.value)&&row.value>0&&row.value<=100&&Number.isFinite(row.checkedAt)&&Number.isFinite(Date.parse(row.updatedAt)))records[server]={...row};}}catch{}
 const save=()=>{try{storage?.setItem(KEY,JSON.stringify(records));}catch{}};
 const quote=server=>{const row=records[server],now=clock(),updated=Date.parse(row?.updatedAt);return row&&now-row.checkedAt<=CACHE_AGE&&row.checkedAt<=now+300000&&now-updated<=MAX_AGE&&updated<=now+300000?{...row}:null;};
 async function refresh(force=false){if(pending)return pending;if(!force&&clock()-lastCheck<900000&&Object.values(IDS).every(quote))return records;pending=(async()=>{try{const response=await fetcher(URL);if(!response.ok)throw Error('HTTP '+response.status);const next=parse(await response.json(),clock());if(!Object.keys(next).length)throw Error('Нет свежей поправки сервера');for(const [server,row]of Object.entries(next))if(!records[server]||Date.parse(row.updatedAt)>=Date.parse(records[server].updatedAt))records[server]=row;lastCheck=clock();error='';save();return records;}catch(e){error='Не удалось обновить поправку сервера: '+e.message;return records;}finally{pending=null;notify();}})();return pending;}
 return {quote,refresh,status:()=>({loading:!!pending,error}),url:URL};
}
const api={URL,parse,create};if(typeof module!=='undefined')module.exports=api;
if(root.document){const service=create({fetcher:url=>root.fetch(url,{signal:AbortSignal.timeout(12000)}),storage:root.localStorage,notify:()=>root.document.dispatchEvent(new Event('economychange'))});root.ServerEconomy=service;root.document.getElementById('refresh').addEventListener('click',()=>service.refresh(true));}
})(typeof window!=='undefined'?window:globalThis);
